from rest_framework.decorators import api_view, permission_classes
from rest_framework.permissions import IsAuthenticated
from rest_framework.response import Response
from rest_framework.exceptions import PermissionDenied
from django_q.models import Task
from .models import DocumentBatchAudit

@api_view(['GET'])
@permission_classes([IsAuthenticated])
def get_ocr_batch_status(request, group_id):
    # Verify that the current user owns the batch submission
    batch = DocumentBatchAudit.objects.filter(group_id=group_id, created_by=request.user).first()
    if not batch:
        raise PermissionDenied("You do not have permission to inspect this batch group")

    tasks = Task.objects.filter(group=group_id)

    results = []
    for t in tasks:
        results.append({
            "task_id": t.id,
            "name": t.name,
            "status": "SUCCESS" if t.success else "PENDING",
            "extracted_document_text": t.result if t.success else None
        })

    return Response({"group_id": group_id, "tasks": results})
